function describe(node, depth, max) {
  const d = '  '.repeat(depth);
  let s = `${d}${node.type} "${node.name}" id=${node.id}`;
  const e = node;
  if (e.characters) s += ` chars="${e.characters}"`;
  if (e.fontName) s += ` font=${e.fontName.family}/${e.fontName.style}`;
  if (typeof e.fontSize === 'number') s += ` size=${e.fontSize}`;
  if (e.fills && Array.isArray(e.fills)) s += ` fills=${JSON.stringify(e.fills.map(f=>({type:f.type,color:f.color,opacity:f.opacity,visible:f.visible} )))}`;
  if (typeof e.cornerRadius === 'number') s += ` corner=${e.cornerRadius}`;
  if (e.width && e.height) s += ` dims=${e.width}x${e.height}`;
  let text = s;
  if ('children' in node && depth < max) {
    (node.children||[]).forEach(c => text += '\n' + describe(c, depth+1, max));
  }
  return text;
}
