// Build plan rows manually using template instance
function buildPlan(photoId, name, goal, level, pct, vy) {
  const pr = figma.getNodeById('19:37').createInstance(); pr.x=24; pr.y=vy; pr.resize(342,84); pr.name=name;
  const ph = pr.children.find(c=>c.name==='Photo'); if(ph){ const inst=figma.getNodeById(photoId).createInstance(); inst.resize(72,72); ph.fills=[{type:'SOLID',color:MUT}]; pr.appendChild(inst); inst.x=14; inst.y=6; }
  const nm=pr.children.find(c=>c.name==='Name'); if(nm)nm.characters=name;
  const gl=pr.children.find(c=>c.name==='Goal'); if(gl)gl.characters=goal;
  const lv=pr.children.find(c=>c.name==='Level'); if(lv)lv.characters=level;
  const pc=pr.children.find(c=>c.name==='Percent'); if(pc)pc.characters=pct+'%';
  const pgr=pr.children.find(c=>c.name==='Progress'); if(pgr)pgr.resize(Math.round(0.01*parseInt(pct)*200),6);
  return pr;
}
