// For each screen, find TabBar instance (its children are tab frames)
function findTabBar(screenNode){
  const tb = screenNode.children.find(c=>c.name==='TabBar');
  if(!tb) return null;
  const tabs = tb.children.filter(c=>c.type==='FRAME' && c.name!=='Rectangle');
  const byName={};
  tabs.forEach(t=>byName[t.name]=t);
