// Helper to set active tab: make icon+label lime/ink
function setActive(tabFrame, active){
  const lbl = tabFrame.children.find(c=>c.type==='TEXT');
  const icon = tabFrame.children.find(c=>c.type==='INSTANCE');
  const activeColor = {r:0.098,g:0.129,b:0.149}; // ink for active
  const inactiveColor = {r:0.55,g:0.58,b:0.62};
  if(active){
    // fill icon vectors with lime
    if(icon) icon.children.forEach(v=>{ v.fills=[{type:'SOLID',color:{r:187/255,g:242/255,b:70/255}}]; });
    if(lbl) lbl.fills=[{type:'SOLID',color:activeColor}];
    // add lime pill under active tab
  } else {
    if(lbl) lbl.fills=[{type:'SOLID',color:inactiveColor}];
  }
}
